import React from 'react';

type FarmState = { targetHumidity: number; irrigationEnabled: boolean; cycleCount: number; status: string };
type FarmProps = { state: FarmState; setState: (update: (current: FarmState) => FarmState) => void };

export default function OrbitalFarmControl({ state, setState }: FarmProps) {
  const rangeState = state.targetHumidity < 55 ? 'DRY' : state.targetHumidity > 72 ? 'HUMID' : 'NOMINAL';
  const accent = rangeState === 'NOMINAL' ? '#64e7b8' : '#ffc968';
  const surface = { padding: 20, border: '1px solid #275256', borderRadius: 18, background: '#0b2528d9' };
  const updateHumidity = (value: number) => setState((current) => ({ ...current, targetHumidity: value, status: `Humidity target set to ${value}%` }));
  const toggleIrrigation = () => setState((current) => ({ ...current, irrigationEnabled: !current.irrigationEnabled, status: current.irrigationEnabled ? 'Irrigation stopped by operator' : 'Irrigation armed for next cycle' }));
  const runCycle = () => setState((current) => { const next = current.cycleCount + 1; return { ...current, cycleCount: next, status: current.irrigationEnabled ? `Cycle ${next} complete · 18-second mist delivered` : `Cycle ${next} logged · no water delivered` }; });

  return (
    <main style={{ minHeight: '100%', boxSizing: 'border-box', padding: 28, color: '#eefbf6', background: 'radial-gradient(circle at 85% 0%, #164b43, #092428 48%, #06191e)', fontFamily: 'Inter, system-ui, sans-serif' }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 22 }}>
        <div><div style={{ color: '#75d9bd', fontSize: 12, fontWeight: 800, letterSpacing: 2 }}>RING HABITAT 04 · BAY C</div><h1 style={{ margin: '7px 0 0', fontSize: 28 }}>Crop Climate Console</h1></div>
        <div style={{ padding: '9px 13px', border: '1px solid #32625d', borderRadius: 999, background: '#0e302e', color: accent, fontSize: 12, fontWeight: 800 }}>● {rangeState}</div>
      </header>
      <section style={{ display: 'grid', gridTemplateColumns: '1.4fr 1fr', gap: 16 }}>
        <div style={surface}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}><label htmlFor="farm-humidity" style={{ color: '#a2c0ba', fontSize: 13, fontWeight: 700 }}>TARGET HUMIDITY</label><strong style={{ color: accent, fontSize: 34 }}>{state.targetHumidity}%</strong></div>
          <input id="farm-humidity" aria-label="Target humidity" type="range" min="40" max="85" value={state.targetHumidity} onChange={(event) => updateHumidity(Number(event.target.value))} style={{ width: '100%', margin: '20px 0 10px', accentColor: '#64e7b8' }} />
          <div style={{ display: 'flex', justifyContent: 'space-between', color: '#6f9791', fontSize: 11 }}><span>40% dry</span><span>55–72% nominal</span><span>85% max</span></div>
        </div>
        <button type="button" aria-pressed={state.irrigationEnabled} onClick={toggleIrrigation} style={{ ...surface, cursor: 'pointer', color: '#effcf7', textAlign: 'left', background: state.irrigationEnabled ? '#12463a' : '#172e32' }}>
          <span style={{ display: 'block', color: '#a2c0ba', fontSize: 12, fontWeight: 700, letterSpacing: 1 }}>IRRIGATION</span><strong style={{ display: 'block', marginTop: 12, fontSize: 24 }}>{state.irrigationEnabled ? 'ON · ARMED' : 'OFF · SAFE'}</strong><span style={{ display: 'block', marginTop: 8, color: '#8fb3ad', fontSize: 12 }}>Tap to {state.irrigationEnabled ? 'suspend' : 'arm'}</span>
        </button>
      </section>
      <section style={{ display: 'grid', gridTemplateColumns: '1fr 1.55fr', gap: 16, marginTop: 16 }}>
        <button type="button" onClick={runCycle} style={{ cursor: 'pointer', padding: 20, border: 0, borderRadius: 18, color: '#062219', background: 'linear-gradient(135deg, #89f4ce, #43c89c)', textAlign: 'left', boxShadow: '0 12px 32px #0006' }}><span style={{ display: 'block', fontSize: 12, fontWeight: 800, letterSpacing: 1 }}>COMPLETED CYCLES</span><strong style={{ display: 'block', margin: '7px 0', fontSize: 36 }}>{state.cycleCount}</strong><span style={{ fontSize: 13, fontWeight: 800 }}>RUN 18-SECOND CYCLE →</span></button>
        <div aria-live="polite" style={surface}><div style={{ color: '#a2c0ba', fontSize: 12, fontWeight: 700, letterSpacing: 1 }}>PERSISTENT STATUS</div><div style={{ marginTop: 14, fontSize: 16, lineHeight: 1.45 }}>{state.status}</div><div style={{ display: 'flex', gap: 17, marginTop: 18, color: '#83a9a3', fontSize: 12 }}><span>EC 1.7</span><span>Reservoir 82%</span><span>Sunlight 18m</span></div></div>
      </section>
    </main>
  );
}
